SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE 1=1 AND "Type of combination" = 'ICI+Chemo';

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE CAST("Cancer type" AS TEXT) LIKE 'Hepatocellular' COLLATE NOCASE AND "Type of combination" = 'ICI+Anti-VEGF';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Cancer type" = 'Non-Small Cell Lung' AND "Monotherapy/combination" = 'Combination' AND "Class of ICI" = 'CTLA-4';

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND 1=1 AND "Monotherapy/combination" = 'Combination' AND "Class of ICI" = 'CTLA-4';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Cancer type" = 'Non-Small Cell Lung' AND "Monotherapy/combination" = 'Combination' AND "Class of ICI" = 'CTLA-4';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Cancer type" = 'Non-Small Cell Lung' AND "Monotherapy/combination" = 'Combination' AND "Class of ICI" = 'CTLA-4';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 2' AND "Monotherapy/combination" = 'Combination' AND "Name of ICI" = 'PD1' AND "Name of ICI" = 'CTLA-4' AND "Cancer type" = 'Head and Neck';

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE "Cancer type" = 'Melanoma' AND CAST("Type of combination" AS TEXT) LIKE 'ICI+Chemo' COLLATE NOCASE;

SELECT "NCT", "Author", "Year", "Originial publication or Follow-up", "Class of ICI", "Cancer type", "Trial phase", "Priamry Multiple, composite, or co-primary endpoints?"
FROM clinical_trials
WHERE ("Class of ICI" = 'PD1' OR "Class of ICI" = 'CTLA-4') AND "Priamry Multiple, composite, or co-primary endpoints?" IN ('Co-primary', 'Dual, unspecified', 'Multiple');

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND 1=1 AND "Monotherapy/combination" = 'Monotherapy' AND "Class of ICI" IS NOT NULL AND "Is PD-L1 positivity inclusion criteria" = 'Yes';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 2' AND "Cancer type" = 'Prostate' AND "Name of ICI" LIKE '%CTLA-4%' AND "Is PD-L1 positivity inclusion criteria" = 'Yes' AND "Monotherapy/combination" = 'Combination';

SELECT "Primary endpoint"
FROM clinical_trials
WHERE "Year" = 2018 AND "Cancer type" = 'Renal cell' AND "Type of combination" = 'ICI+Chemo';

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Monotherapy/combination" = 'Combination' AND "Class of ICI" = 'PD-L1' AND 1=1;

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND ("Cancer type" = 'Renal cell' OR "Cancer type" = 'Hodgkin Lymphoma') AND "Monotherapy/combination" = 'Combination' AND "Class of ICI" = 'PD-L1' AND 1=1;

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE 1=1 AND "Type of combination" = 'ICI+Vaccine';

SELECT "Cancer type", "Follow-up duration for primary endpoint(s) in months | Overall"
FROM clinical_trials
WHERE "Cancer type" = 'Non-Small Cell Lung' AND "Name of ICI" = 'Tremelimumab' AND "Follow-up duration for primary endpoint(s) in months | Overall" > 21;

SELECT "NCT", "Author", "Year", "Originial publication or Follow-up", "Class of ICI", "Cancer type", "Trial phase", "Priamry Multiple, composite, or co-primary endpoints?"
FROM clinical_trials
WHERE ("Class of ICI" = 'PD-L1' OR "Class of ICI" = 'CTLA-4') AND "Priamry Multiple, composite, or co-primary endpoints?" = 'Co-primary';

SELECT "Year"
FROM clinical_trials
WHERE "Cancer type" = 'Small Cell Lung' AND "Class of ICI" = 'PD1' AND "Included in MA" = 'Yes' AND "Year" >= 1900;

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE CAST("Trial phase" AS TEXT) LIKE '%Phase 2%' COLLATE NOCASE AND CAST("Name of ICI" AS TEXT) LIKE '%Durvalumab%' COLLATE NOCASE AND CAST("Name of ICI" AS TEXT) LIKE '%Tremelimumab%' COLLATE NOCASE AND CAST("Cancer type" AS TEXT) LIKE '%Colorectal%' COLLATE NOCASE;

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Class of ICI" = 'CTLA-4' AND "Monotherapy/combination" = 'Combination' AND 1=1;

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE CAST("Cancer type" AS TEXT) LIKE '%Colorectal%' COLLATE NOCASE AND CAST("Name of ICI" AS TEXT) LIKE '%Durvalumab%' COLLATE NOCASE AND CAST("Name of ICI" AS TEXT) LIKE '%Tremelimumab%' COLLATE NOCASE AND CAST("Trial phase" AS TEXT) LIKE '%Phase 2%' COLLATE NOCASE;

SELECT "Primary endpoint"
FROM clinical_trials
WHERE "Cancer type" = 'Prostate' AND "Monotherapy/combination" = 'Combination' AND "Treatment regimen" LIKE '%radiation therapy%' AND "Name of ICI" IS NOT NULL;
